Implement the Verilog module based on the following description.
Build a 3-bit shift register (left shift) with synchronous active high reset and enable signals.
// (1) reset: Resets shift register to zero.
// (2) ena: Enable shifting.
// (3) d: Data input.
// (4) q: The contents of the shift register.

module top_module(
    input clk,
    input reset,
    input ena,
    input d,
    output reg [2:0] q);

code:
module top_module(
    input clk,
    input reset,
    input ena,
    input d,
    output reg [2:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the shift register to zero
            q <= 3'b000;
        end else if (ena) begin
            // Enable: Shift left and input new data
            q <= {q[1:0], d};
        end
    end

endmodule

