    clk_i,
    start_i,
    PCWrite_i,
    pc_i,
    pc_o
);input               clk_i, PCWrite_i;
input               start_i;
input   [31:0]      pc_i;
output  [31:0]      pc_o;


reg     [31:0]      pc_o;


always@(negedge clk_i or negedge start_i) begin

