Implement the Verilog module based on the following description.
Build a 4-bit ring counter with synchronous active low reset signal. The counter should shift its bits to the left and wrap around the most significant bit to the least significant bit.
// (1) reset_n: Resets the counter to 4'b0001 when low.
// (2) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    output reg [3:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    output reg [3:0] q
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the counter to 4'b0001
            q <= 4'b0001;
        end else begin
            // Ring counter: Shift left and wrap around MSB to LSB
            q <= {q[2:0], q[3]};
        end
    end

endmodule

