				else if (lo==1)
					Wdata<={16'h0000,MFRTMout[7:0],8'h00};
				else if (lo==2)
					Wdata<={8'h00,MFRTMout[7:0],16'h0000};
				else if (lo==3)
					Wdata<={MFRTMout[7:0],24'h000000};
				else
